# Generated by test-lab — blind adversarial evaluation
"""Contract tests for the mutation-load specimen-population gate.

Live proof of the bad-genetic-material rate is the qualification matrix
(real Docker compile + review over champion mutants). These tests lock the
deterministic, auditable properties of the gate that make that rate trustworthy:
  * mutation is seed-deterministic (same seed -> byte-identical variant set),
  * every variant records its edit_count + mutation_ops (auditable, not tuned),
  * the shared review gate rejects a role-interface-broken artifact,
  * the champion is never counted in the bad-rate denominator.

They avoid Docker: the compile step is monkeypatched so the tests stay hermetic
and fast. The Docker path itself is exercised live by the matrix.
"""
from __future__ import annotations

import sys
from pathlib import Path

import pytest

_SRC = Path(__file__).resolve().parent.parent / "src"
if str(_SRC) not in sys.path:
    sys.path.insert(0, str(_SRC))

from battle_skill import adaptive_specimen_population as pop
from battle_skill.team_artifact_pipeline import review_artifact_errors

_RED_CHAMPION = (
    "import app\n"
    "from app import import_zip\n"
    "\n"
    "def run():\n"
    "    if True:\n"
    "        return import_zip('x')\n"
)


def _all_compile_ok(_population_dir: Path, _docker_image: str) -> dict:
    # Report every variant file as compiling; isolates review/ledger logic.
    return {p.name: {"file": p.name, "ok": True} for p in _population_dir.glob("*.py")}


def test_mutation_is_seed_deterministic(tmp_path: Path, monkeypatch) -> None:
    monkeypatch.setattr(pop, "_compile_all", _all_compile_ok)
    kwargs = dict(team="red", generation=1, seed=7, variants=8, max_edits=5)
    a = pop.run_specimen_population(
        champion_source=_write(tmp_path / "a.py"), out_dir=tmp_path / "A", **kwargs
    )
    b = pop.run_specimen_population(
        champion_source=_write(tmp_path / "b.py"), out_dir=tmp_path / "B", **kwargs
    )
    assert [r["mutation_ops"] for r in a["ledger"]] == [r["mutation_ops"] for r in b["ledger"]]
    assert a["variants_rejected"] == b["variants_rejected"]


def test_every_variant_is_auditable(tmp_path: Path, monkeypatch) -> None:
    monkeypatch.setattr(pop, "_compile_all", _all_compile_ok)
    res = pop.run_specimen_population(
        champion_source=_write(tmp_path / "c.py"),
        team="red", generation=1, seed=3, out_dir=tmp_path / "C", variants=8, max_edits=5,
    )
    for row in res["ledger"]:
        assert row["edit_count"] >= 1
        assert len(row["mutation_ops"]) == row["edit_count"]
        assert isinstance(row["accepted"], bool)
        if not row["accepted"]:
            assert row["reject_reason"]


def test_champion_excluded_from_bad_rate_denominator(tmp_path: Path, monkeypatch) -> None:
    monkeypatch.setattr(pop, "_compile_all", _all_compile_ok)
    res = pop.run_specimen_population(
        champion_source=_write(tmp_path / "d.py"),
        team="red", generation=1, seed=1, out_dir=tmp_path / "D", variants=8, max_edits=5,
    )
    assert res["variants_sampled"] == 8  # champion is not one of the sampled mutants
    assert res["variants_accepted"] + res["variants_rejected"] == 8
    assert res["survivor_pool_size"] == res["variants_accepted"] + 1  # + parent champion


def test_review_gate_rejects_broken_role_interface() -> None:
    # Red artifact that drops the app import interface must be rejected by the shared gate.
    assert review_artifact_errors("red", "def run():\n    return 1\n")
    assert not review_artifact_errors("red", _RED_CHAMPION)


def _write(path: Path) -> Path:
    path.write_text(_RED_CHAMPION, encoding="utf-8")
    return path
